class WindowSchema:
    """Field/column layout of one job plus its AST predicate definitions."""

    def __init__(self, job: dict[str, Any]):
        self.job = job
        self.order: list[str] = [field["name"] for field in job["fields"]]
        self.names: dict[str, int] = {name: index for index, name in enumerate(self.order)}
        self.types: dict[str, str] = {field["name"]: field["type"] for field in job["fields"]}
        self.field_domains: list[list[int]] = [list(field["domain"]) for field in job["fields"]]
        self.slots: int = int(job["slots"])
        self.nf: int = len(self.order)
        self.domains: list[list[int]] = [
            list(field["domain"]) for _ in range(self.slots) for field in job["fields"]
        ]
        self.columns: list[str] = [f"cell_{index}" for index in range(len(self.domains))]
        self.positions: dict[str, int] = {name: index for index, name in enumerate(self.columns)}
        self.families: dict[str, list[str]] = {
            field["name"]: [
                self.columns[self.position([slot, field["name"]])] for slot in range(self.slots)
            ]
            for field in job["fields"]
        }
        self.fields: dict[str, FieldSpec] = {
            self.columns[slot * self.nf + index]: FieldSpec(
                name=self.columns[slot * self.nf + index],
                value_type=ValueType.INTEGER,
                roles=[FieldRole(field["type"]) if field["type"] != "id" else FieldRole.IDENTIFIER],
                domain=list(field["domain"]),
                context_family=field["name"],
                context_index=slot,
            )
            for slot in range(self.slots)
            for index, field in enumerate(job["fields"])
        }
        self.spec = DatasetSpec(
            name="finite-windows",
            source=SourceSpec(type=SourceType.CSV),
            fields=list(self.fields.values()),
        )

    def position(self, ref: list[Any]) -> int:
        """Flattened cell index of a ``[slot, field_name]`` reference."""
        return ref[0] * self.nf + self.names[ref[1]]

    def term(self, term: dict[str, Any]) -> Any:
        """Translate a protocol term into the NetNomos term AST."""
        if "const" in term:
            return Constant(term["const"])
        if "sum" in term:
            return FuncCall("sum", tuple(SymbolRef(self.columns[self.position(ref)]) for ref in term["sum"]))
        ref = SymbolRef(self.columns[self.position(term["ref"])])
        return BinaryTerm("*", Constant(term["scale"]), ref) if "scale" in term else ref

    def predicates(self) -> list[GroundedPredicate]:
        """Grounded AST form of every input predicate, keeping input ids."""
        result: list[GroundedPredicate] = []
        for index, predicate in enumerate(self.job["predicates"]):
            op = Comparator(OPS[predicate["op"]])
            if predicate["kind"] == "cmp":
                formula: Formula = Compare(op.value, self.term(predicate["left"]), self.term(predicate["right"]))
                display = formula_to_string(formula)
            else:
                template = QuantifierTemplateSpec(
                    name="window",
                    quantifier="exists" if predicate["kind"] == "any" else "forall",
                    selector=VariableSelectorSpec(),
                    operators=[op],
                    constant=ConstantSelectorSpec(mode="explicit", values=[predicate["value"]]),
                )
                formula, display = project_quantified_family(
                    predicate["field"],
                    self.families[predicate["field"]],
                    template,
                    op,
                    SelectedConstant(predicate["value"], None),
                )
            result.append(
                GroundedPredicate(
                    str(index),
                    formula,
                    display,
                    0.0,
                    {"position": index, "kind": predicate["kind"]},
                )
            )
